<?php $this->load->view('library_workspace/header'); ?>
<div class="card"><div class="card-header"><h2 class="card-title"><?= html_escape($definition['title']); ?></h2><div class="network-actions ms-auto"><a class="btn btn-primary" href="<?= html_escape($network_url('edit/'.$entity)); ?>">Tambah</a><a class="btn btn-outline-primary" href="<?= html_escape($network_url('import/'.$entity)); ?>">Impor Excel</a><?php foreach(['csv'=>'CSV','xlsx'=>'Excel']as$ext=>$label): ?><a class="btn network-export-<?= $ext; ?>" href="<?= html_escape($network_url('export/'.$entity.'/'.$ext).'&q='.rawurlencode($q)); ?>"><i class="ti ti-download me-1"></i><?= $label; ?></a><?php endforeach; ?></div></div>
<div class="card-body border-bottom"><form method="get" class="row g-2"><input type="hidden" name="library_id" value="<?= (int)$scope; ?>"><div class="col-md-7"><input class="form-control" name="q" value="<?= html_escape($q); ?>" placeholder="Cari nama/judul, nomor, ISBN, atau barcode"></div><div class="col-md-3"><select class="form-select" name="per_page"><?php foreach([10,25,50,100]as$n): ?><option value="<?= $n; ?>" <?= $n===$per_page?'selected':''; ?>><?= $n; ?> baris</option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filter</button></div></form></div>
<div class="table-responsive"><table class="table table-vcenter"><thead><tr><?php foreach($definition['columns']as$label): ?><th><?= html_escape($label); ?></th><?php endforeach; ?><th>Aksi</th></tr></thead><tbody>
<?php foreach($result['rows']as$row): ?><tr><?php foreach($definition['columns']as$key=>$label): ?><td><?= html_escape(in_array($key,['status','format','gender'],true)?$network_label($row[$key]):($row[$key]?:'—')); ?></td><?php endforeach; ?><td><div class="network-actions"><a class="btn btn-sm btn-outline-primary" href="<?= html_escape($network_url('edit/'.$entity.'/'.$row['id'])); ?>"><i class="ti ti-edit me-1"></i>Edit</a><?php if($entity==='books'&&$row['format']==='physical'): ?><a class="btn btn-sm btn-outline-primary" href="<?= html_escape($network_url('edit/items').'&book_id='.(int)$row['id']); ?>">Tambah eksemplar</a><?php endif; ?><form method="post" action="<?= html_escape($network_url('archive/'.$entity.'/'.$row['id'])); ?>" onsubmit="return confirm('Arsipkan data ini? Histori tetap disimpan.');"><input type="hidden" name="network_csrf" value="<?= html_escape($csrf); ?>"><button class="btn btn-sm btn-outline-danger">Arsipkan</button></form></div></td></tr><?php endforeach; ?>
<?php if(!$result['rows']): ?><tr><td colspan="<?= count($definition['columns'])+1; ?>" class="text-center text-secondary py-4">Belum ada data yang sesuai.</td></tr><?php endif; ?></tbody></table></div>
<div class="card-footer d-flex"><span><?= number_format($result['total']); ?> data · halaman <?= $page; ?>/<?= $pages; ?></span><div class="network-actions ms-auto"><?php if($page>1): ?><a class="btn btn-sm" href="<?= html_escape($network_url('records/'.$entity).'&'.http_build_query(['q'=>$q,'per_page'=>$per_page,'page'=>$page-1])); ?>">Sebelumnya</a><?php endif; ?><?php if($page<$pages): ?><a class="btn btn-sm" href="<?= html_escape($network_url('records/'.$entity).'&'.http_build_query(['q'=>$q,'per_page'=>$per_page,'page'=>$page+1])); ?>">Berikutnya</a><?php endif; ?></div></div></div>
<?php $this->load->view('library_workspace/footer'); ?>
